<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import * as api from '@/api/practice-paper'
import {catalogDateCounts} from '@/practice/catalog-date-counts'
import type {Filters} from '@/practice/catalog-query'
import {errorMessage} from '@/api/identity'
import {useAuthStore} from '@/stores/auth'
import {useAuthDialogStore} from '@/stores/auth-dialog'
import {onRemoteIdentityChange} from '@/auth/token-session'
import '@/styles/practice-paper.css'
import PracticePaperFilters from '@/components/practice/PracticePaperFilters.vue'
import PracticePaperMistakes from '@/components/practice/PracticePaperMistakes.vue'
import {ApiError} from '@/api/client'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),login=useAuthDialogStore(),catalog=ref<api.PaperCatalog|null>(null),history=ref<api.PaperHistory[]>([]),total=ref(0),loaded=ref(false),busy=ref(false),error=ref(''),actionBusy=ref(false)
const filterDialog=ref<HTMLDialogElement>()
const mistakes=ref<api.PaperMistake[]>([]),activeReview=ref(''),retryIds=new Map<string,string>()
const mistakeTab=computed(()=>route.query.tab==='mistakes')
let epoch=0,controller:AbortController|undefined
const labels:Record<string,string>={writing:'写作',listening:'听力',reading:'阅读',translation:'翻译',paper:'整卷'}
function catalogTitle(p:api.PaperView){
  const exam=p.examCode==='CET4'?'四级':p.examCode==='CET6'?'六级':''
  if(!exam||!p.year||!p.month)return p.title
  const paper=p.title.match(/第\s*([0-9]+)\s*套/)
  return `${p.year}年${p.month}月${exam}${paper?' 第'+paper[1]+'套':''} 完整试卷`
}

async function load(){if(route.query.section!=='paper')return;const n=++epoch;controller?.abort();controller=new AbortController();busy.value=true;error.value='';try{const q=new URLSearchParams();for(const key of ['exam','year','month','page'])if(route.query[key])q.set(key,String(route.query[key]));const data=await catalogDateCounts(q,query=>api.listPapers(query,controller!.signal),'years');if(n!==epoch)return;catalog.value=data;if(mistakeTab.value){if(!auth.user){login.request(route.fullPath);mistakes.value=[];total.value=0;return}if(route.query.mistakeType)q.set('readingType',String(route.query.mistakeType));if(route.query.sourceAttemptId)q.set('sourceAttemptId',String(route.query.sourceAttemptId));q.set('status',String(route.query.mistakeStatus||'PENDING'));const result=await api.paperMistakes(q,controller.signal);if(n!==epoch)return;mistakes.value=result.items;total.value=result.total}else if(route.query.tab==='history'){if(!auth.user){login.request(route.fullPath);history.value=[];total.value=0;return}const h=await api.listPaperHistory(q,controller.signal);if(n!==epoch)return;history.value=h.items;total.value=h.total}else total.value=data.total;loaded.value=true}catch(e){if(n===epoch&&!(e instanceof DOMException&&e.name==='AbortError'))error.value=errorMessage(e)}finally{if(n===epoch)busy.value=false}}
function set(key:string,value:string){const query={...route.query,[key]:value||undefined};if(key==='section'&&value!=='paper'){delete query.sourceAttemptId;delete query.mistakeStatus;delete query.mistakeType}if(key!=='page')delete query.page;if(key==='year'||key==='exam')delete query.month;void router.replace({query})}
function applyFilters(filters:Filters){void router.replace({query:{...route.query,exam:filters.exam,year:filters.year||undefined,month:filters.month||undefined,page:undefined}})}
async function start(p:api.PaperView){if(!auth.user){login.request(route.fullPath);return}if(actionBusy.value)return;actionBusy.value=true;error.value='';try{const a=await api.startPaper(p.id,p.paperVersionId!,crypto.randomUUID());await router.push({path:'/practice/paper-attempts/'+a.id,query:{returnTo:route.fullPath}})}catch(e){error.value=errorMessage(e)}finally{actionBusy.value=false}}
function viewSource(item:api.PaperMistake){void router.push({path:'/practice/paper-attempts/'+item.sourceAttemptId,query:{slot:item.slot,questionId:item.questionId,returnTo:route.fullPath}})}
async function review(item:api.PaperMistake){if(actionBusy.value)return;const n=epoch,owner=auth.user?.id,key=item.sourceAttemptId+':'+item.slot;const requestId=retryIds.get(key)||crypto.randomUUID();retryIds.set(key,requestId);actionBusy.value=true;error.value='';activeReview.value='';try{const run=await api.retryPaperMistakes(item.sourceAttemptId,{requestId,slot:item.slot});if(n===epoch&&owner===auth.user?.id){retryIds.delete(key);await router.push({path:'/practice/attempts/'+run.id,query:{returnTo:route.fullPath}})}}catch(e){if(n===epoch){error.value=errorMessage(e);const id=e instanceof ApiError?e.fieldErrors?.activeAttemptId:undefined;if(id&&/^\d+$/.test(id))activeReview.value=id}}finally{actionBusy.value=false}}
watch(()=>route.fullPath,load,{immediate:true});const off=onRemoteIdentityChange(()=>{history.value=[];mistakes.value=[];activeReview.value='';retryIds.clear();loaded.value=false;void load()});onBeforeUnmount(()=>{epoch++;controller?.abort();off()})
</script>
<template><section class="practice-page paper-page practice-catalog-page"><RouterLink class="reading-back practice-back" :to="{path:'/practice',query:{source:'PAST'}}">← 返回考试类别</RouterLink><header class="paper-heading"><h1>大学英语（四六级）</h1></header><nav class="paper-tabs" aria-label="练习题型"><button v-for="(label,key) in labels" :key="key" :aria-pressed="key==='paper'" @click="set('section',key)">{{label}}</button></nav><div class="paper-tabs" role="tablist" aria-label="整卷栏目"><button role="tab" :aria-selected="!['history','mistakes'].includes(String(route.query.tab))" @click="set('tab','sets')">全部试卷</button><button role="tab" :aria-selected="route.query.tab==='history'" @click="set('tab','history')">我的练习</button><button role="tab" :aria-selected="mistakeTab" @click="set('tab','mistakes')">错题本</button></div><button class="practice-filter-toggle" @click="filterDialog?.showModal()">筛选题组</button><div class="paper-library"><aside class="practice-desktop-filters"><PracticePaperFilters :query="route.query" :catalog="catalog" :dates-pending="busy||!!error" @apply="applyFilters"/></aside><div class="paper-results" :aria-busy="busy"><p class="paper-summary">匹配 {{loaded?total:'—'}} {{mistakeTab?'道错题':route.query.tab==='history'?'轮练习':'套'}} <span role="status">{{busy?'正在加载…':''}}</span></p><p v-if="error" role="alert" class="paper-error">{{error}} <button @click="load">重试</button></p><template v-if="mistakeTab"><div class="paper-actions paper-mistake-filters"><label>错题状态<select aria-label="整卷错题状态" :value="route.query.mistakeStatus||'PENDING'" @change="set('mistakeStatus',($event.target as HTMLSelectElement).value)"><option value="PENDING">待订正</option><option value="RESOLVED">已订正</option></select></label><label>题型<select aria-label="整卷错题题型" :value="route.query.mistakeType||''" @change="set('mistakeType',($event.target as HTMLSelectElement).value)"><option value="">全部题型</option><option value="LISTENING">听力</option><option value="CLOZE">选词填空</option><option value="MATCH">长篇匹配</option><option value="DETAILED">仔细阅读</option></select></label><button v-if="route.query.sourceAttemptId" @click="set('sourceAttemptId','')">查看全部整卷错题</button></div><RouterLink v-if="activeReview" :to="{path:'/practice/attempts/'+activeReview,query:{returnTo:route.fullPath}}">继续已有错题练习</RouterLink><PracticePaperMistakes :items="mistakes" :busy="actionBusy" @view="viewSource" @review="review"/></template><template v-else-if="route.query.tab==='history'"><article v-for="h in history" :key="h.id" class="paper-panel paper-row"><div><h2>{{h.title}}</h2><p>{{h.status==='COMPLETED'?'已完成':'进行中'}} · {{new Date(h.startedAt).toLocaleString()}}</p></div><RouterLink class="paper-primary" :to="{path:'/practice/paper-attempts/'+h.id,query:{returnTo:route.fullPath}}">{{h.status==='COMPLETED'?'查看作答与参考':'继续练习'}}</RouterLink></article></template><template v-else><div v-if="busy&&!catalog" class="paper-loading-rows" aria-hidden="true"><div v-for="i in 3" :key="i" class="practice-catalog-placeholder"></div></div><article v-for="p in catalog?.items" :key="p.id" class="paper-panel paper-row practice-catalog-row"><div class="practice-set-copy"><h2>{{catalogTitle(p)}}</h2><p v-if="!p.available" class="paper-error">{{p.unavailableReason}}</p></div><div class="paper-tags"><span v-if="p.currentAttemptId">可继续</span><span>完整试卷</span><span>{{p.month}}月</span></div><button class="paper-primary" :disabled="actionBusy||(!p.available&&!p.currentAttemptId)" @click="start(p)">{{p.currentAttemptId?'继续练习':'开始练习'}}</button></article></template><p v-if="!busy&&!error&&!total" class="paper-panel">{{mistakeTab?'当前没有符合条件的整卷错题。':route.query.exam==='CET6'?'六级整卷尚未开放。':route.query.tab==='history'?'还没有符合条件的整卷记录。':'暂无已发布整卷，可调整筛选。管理员须先完成组卷校对和发布。'}}</p><details v-if="!mistakeTab&&route.query.tab!=='history'&&catalog?.items.length" class="practice-catalog-notes"><summary>试卷与来源说明</summary><article v-for="p in catalog.items" :key="p.id"><h3>{{p.title}}</h3><p>{{p.year}}年{{p.month}}月 · 写作1题、听力25题、阅读30题、翻译1题</p><p>{{p.sourceNote}}</p></article></details><nav class="paper-actions"><button :disabled="busy||Number(route.query.page||1)<=1" @click="set('page',String(Number(route.query.page||1)-1))">上一页</button><span>第 {{route.query.page||1}} / {{Math.max(1,Math.ceil(total/20))}} 页</span><button :disabled="busy||Number(route.query.page||1)*20>=total" @click="set('page',String(Number(route.query.page||1)+1))">下一页</button></nav></div></div><dialog ref="filterDialog" class="practice-preview-dialog practice-page"><button @click="filterDialog?.close()">关闭</button><PracticePaperFilters :query="route.query" :catalog="catalog" :dates-pending="busy||!!error" @apply="applyFilters"/></dialog></section></template>
